// --- 送信時の確認（#2050）-------------------------------------------------------------

type GuardFinding = { rule: string; line: number; masked: string }
type GuardCheck = { verdict?: string; findings?: GuardFinding[] }

// 当たりの要約（規則名と伏せ字だけ。tako の応答に生の値は無い）
function guardFound(findings: readonly GuardFinding[]): string {
  const shown = findings.slice(0, GUARD_SHOW_MAX).map(f => `${f.rule} ${f.masked}`)
  const rest = findings.length - shown.length
  return rest > 0 ? `${shown.join(', ')} +${rest}` : shown.join(', ')
}

// 送る前に tako へ判定させ、答えに従う。'drop' = 送らない。CLI の失敗・時間切れは送信を通す
async function guardPrompt($: EngineInterface, text: string): Promise<'pass' | 'drop'> {
  const path = cli
  const pane = paneId
  if (path === undefined || pane === undefined || text.trim() === '') return 'pass'
  let check: GuardCheck
  try {
    const done = await $.process.run([path, 'paste-guard', 'check', '--pane', pane], {
      stdin: text,
      timeoutMs: GUARD_TIMEOUT_MS,
    })
    if (done.exitCode !== 0) {
      $.ui.log(`tako mod: paste-guard exit ${done.exitCode}`, { to: 'debug' })
      return 'pass'
    }
    check = JSON.parse(done.stdout) as GuardCheck
  } catch {
    $.ui.log('tako mod: paste-guard check failed', { to: 'debug' })
    return 'pass'
  }
  const w = words(lang)
  const found = guardFound(check.findings ?? [])
  if (check.verdict === 'warn') {
    $.ui.toast(w.guardWarned(found), { timeoutMs: 8_000 })
    return 'pass'
  }
  if (check.verdict !== 'confirm') return 'pass'
  // 「やめる」を先頭（既定の選択）に置く: 送信のつもりで押した Enter で送らない（#2046 と同じ考え）
  let answer: string
  try {
    answer = await $.ui.ask(w.guardQuestion(found), { options: [w.guardCancel, w.guardSend], header: w.guardHeader })
  } catch {
    // 閉じた（Esc）= やめる
    answer = w.guardCancel
  }
  if (answer === w.guardSend) return 'pass'
  await restoreDraft($, text)
  return 'drop'
}

// やめた送信の文を入力欄へ戻す（鍵を消して送り直せるように。スマホの PWA と同じ）。
// 戻せなくても送らないことは変えない
async function restoreDraft($: EngineInterface, text: string): Promise<void> {
  try {
    await $.prompt.fill({ text, mode: 'replace' })
  } catch {
    $.ui.log('tako mod: paste-guard draft restore failed', { to: 'debug' })
  }
}

// 端末の桁数（全角・CJK は 2 桁。Claude Code の配置と同じ数え方の近似）
function isWide(c: number): boolean {
  return (
    (c >= 0x1100 && c <= 0x115f) ||
    (c >= 0x2e80 && c <= 0xa4cf) ||
    (c >= 0xac00 && c <= 0xd7a3) ||
    (c >= 0xf900 && c <= 0xfaff) ||
    (c >= 0xfe30 && c <= 0xfe4f) ||
    (c >= 0xff00 && c <= 0xff60) ||
    (c >= 0xffe0 && c <= 0xffe6) ||
    (c >= 0x20000 && c <= 0x3fffd)
  )
}

function cellWidth(text: string): number {
  let width = 0
  for (const ch of text) width += isWide(ch.codePointAt(0) ?? 0) ? 2 : 1
  return width
}

// max 桁に収める（溢れたら末尾を … にする）
function clipCells(text: string, max: number): string {
  if (cellWidth(text) <= max) return text
  let out = ''
  let width = 0
  for (const ch of text) {
    const w = isWide(ch.codePointAt(0) ?? 0) ? 2 : 1
    if (width + w > max - 1) break
    out += ch
    width += w
  }
  return `${out}…`
}

function limitName(kind: string): string {
  if (kind === 'five_hour') return '5h'
  if (kind === 'seven_day') return '7d'
  if (kind.startsWith('seven_day_')) return `7d ${kind.slice('seven_day_'.length)}`
  return kind.replace(/_/g, ' ')
}

/** 帯の区切り 1 つ。rank が小さいほど最後まで残す（0 / 1 = tako とペイン名は落とさない） */
type BandSegment = { kind: string; label: string; tone?: 'warning' | 'accent'; rank: number }

/** 押したときにすること（#1962）。tako / shell の argv は tako が組んだもの（view.button_args） */
type Press = { kind: 'slash'; command: string } | { kind: 'prompt'; text: string } | { kind: 'tako' | 'shell'; argv: string[] }

/** 帯のボタン 1 つ（#1962）。rank は区切りと同じ物差し（左のボタンほど最後まで残す） */
type BandButton = { button: TakoButton; press: Press; rank: number }

/** 帯のカードのボタンの操作（#1963）。code は「最新のコードをコピー」（#1964。同じ plain の形で並べる） */
type CardOp = 'copy' | 'run' | 'next' | 'dismiss' | 'code'
/** 帯のカードのボタン 1 つ（#1963）。`y: コピー` の形（plain = ホットキーを見せる）で描く */
type CardButton = { op: CardOp; label: string; hotkey: string; rank: number }
/** 帯で選んでいるカードのコマンド（#1963）。pairs は新しいカードから（カード, コマンド）の並び */
type CardPair = { card: TakoCard; index: number; command: TakoCardCommand }
type CardSel = CardPair & { pos: number; pairs: CardPair[] }

// 帯の区切りを左から並べる（何を出すかは tako の view が決めている）。
// s3 = #1881 の並び（A/B の S3 の描き方と、ui.json が届かない古い tako の応答）。S7 は ui.json の
// band.segments の並びで、バーの置き場が帯なら bar（tako が描くと決めたバーの文字列）を ctx / limits の
// 位置（無ければボタンの前）に 1 つ置く（バーを描くなら tako は警告を送ってこない = 同じ値を 2 か所で
// 動かさない）
function segmentsOf(view: TakoView, s3: boolean, bar: string | null, card: CardSel | null = null): BandSegment[] {
  const w = words(view.lang)
  const name = view.pane_title ?? `pane ${view.pane}`
  const pane: BandSegment = { kind: 'pane', label: clipCells(name, NAME_MAX), rank: 1 }
  const hasTab = view.tab_title !== undefined && view.tab_title !== '' && view.tab_title !== name
  const tab = (rank: number): BandSegment => ({ kind: 'tab', label: `${w.tab} ${clipCells(view.tab_title ?? '', NAME_MAX)}`, rank })
  const workers = (rank: number): BandSegment => ({ kind: 'workers', label: w.workers(view.worker_count), rank })
  const attention: BandSegment = { kind: 'attention', label: w.attention(view.attention), tone: 'warning', rank: 2 }
  // 使用制限は % の大きい順に来る。小さい方から落とす
  const warning = (warn: TakoView['warnings'][number], i: number, base: number): BandSegment => {
    const pct = `${Math.round(warn.percent)}%`
    return warn.kind === 'ctx'
      ? { kind: 'ctx', label: `ctx ${pct}`, tone: 'warning', rank: base }
      : { kind: warn.kind, label: `${limitName(warn.kind)} ${pct}`, tone: 'warning', rank: base + 1 + i / 100 }
  }
  if (s3) {
    const out: BandSegment[] = [{ kind: 'tako', label: 'tako', rank: 0 }, pane]
    if (hasTab) out.push(tab(6))
    if (view.worker_count > 0) out.push(workers(5))
    if (view.attention > 0) out.push(attention)
    view.warnings.forEach((warn, i) => out.push(warning(warn, i, 3)))
    return out
  }
  const out: BandSegment[] = [{ kind: 'tako', label: 'tako', tone: 'accent', rank: 0 }]
  let barPlaced = bar === null
  const placeBar = (): void => {
    if (!barPlaced) out.push({ kind: 'usage', label: bar ?? '', rank: 4 })
    barPlaced = true
  }
  for (const seg of view.ui?.band.segments ?? DEFAULT_SEGMENTS) {
    if (seg === 'pane') out.push(pane)
    else if (seg === 'tab' && hasTab) out.push(tab(7))
    else if (seg === 'workers' && view.worker_count > 0) out.push(workers(6))
    else if (seg === 'attention' && view.attention > 0) out.push(attention)
    else if ((seg === 'ctx' || seg === 'limits') && bar !== null) placeBar()
    else if (seg === 'ctx') view.warnings.filter(warn => warn.kind === 'ctx').forEach((warn, i) => out.push(warning(warn, i, 4)))
    else if (seg === 'limits') view.warnings.filter(warn => warn.kind !== 'ctx').forEach((warn, i) => out.push(warning(warn, i, 4)))
    else if (seg === 'buttons') placeBar()
    else if (seg === 'card' && card !== null) {
      // #1963: `カード N`（会話の行の見出しと同じ番号 = tako のカード id）と、選んでいるコマンドの頭
      const of = card.card.commands.length
      out.push({ kind: 'card', label: of > 1 ? `${w.card(card.card.id)} (${card.index}/${of})` : w.card(card.card.id), tone: 'accent', rank: 2.52 })
      out.push({ kind: 'card_head', label: clipCells(card.command.text.split('\n')[0] ?? '', CARD_HEAD_MAX), rank: 3.9 })
    }
  }
  placeBar()
  return out
}

// 帯のボタン（#1962。ui.json の buttons の並び）。押せないもの（Claude Code に無いコマンド・tako が
// 引数を組めなかった操作）は描かない。band.segments に buttons が無ければ 1 つも描かない
function buttonsOf(view: TakoView): BandButton[] {
  const segments: readonly TakoBandSegment[] = view.ui?.band.segments ?? DEFAULT_SEGMENTS
  if (!segments.includes('buttons')) return []
  const out: BandButton[] = []
  ;(view.ui?.buttons ?? []).forEach((button, i) => {
    const action = button.action
    let press: Press | undefined
    if (action.kind === 'slash') {
      if (commandNames === undefined || commandNames.has(action.command)) press = { kind: 'slash', command: action.command }
    } else if (action.kind === 'prompt') {
      press = { kind: 'prompt', text: action.text }
    } else {
      const argv = view.button_args?.[button.id]
      if (argv !== undefined) press = { kind: action.kind, argv }
    }
    if (press !== undefined) out.push({ button, press, rank: 3 + i / 100 })
  })
  return out
}

function lineWidth(segments: readonly BandSegment[]): number {
  return segments.reduce((sum, seg, i) => sum + cellWidth(seg.label) + (i === 0 ? 0 : SEP.length), 0)
}

// tako の行の桁: 区切りの Text と、ボタン 1 つごとに間の 1 桁 + `[ ` ラベル ` ]`（カードのボタンは
// `y: ` ラベル）
function rowWidth(segments: readonly BandSegment[], buttons: readonly BandButton[], cards: readonly CardButton[] = []): number {
  return (
    lineWidth(segments) +
    buttons.reduce((sum, b) => sum + BUTTON_GAP + BUTTON_CHROME + cellWidth(b.button.label), 0) +
    cards.reduce((sum, b) => sum + BUTTON_GAP + PLAIN_CHROME + cellWidth(b.label), 0)
  )
}

// columns 桁に収まるまで、優先度の低いもの（区切りもボタンも同じ物差し）から落とす（並びは変えない）。
// tako とペイン名だけでも溢れる幅では、描画側の wrap="truncate-end" が末尾を切る = 必ず 1 行
function fitBand(
  segments: BandSegment[],
  buttons: BandButton[],
  columns: number,
  cards: CardButton[] = [],
): { segments: BandSegment[]; buttons: BandButton[]; cards: CardButton[] } {
  let keptSegments = segments
  let keptButtons = buttons
  let keptCards = cards
  const order: Array<BandSegment | BandButton | CardButton> = [...segments, ...buttons, ...cards].sort((a, b) => b.rank - a.rank)
  for (const drop of order) {
    if (rowWidth(keptSegments, keptButtons, keptCards) <= columns || drop.rank <= 1) break
    keptSegments = keptSegments.filter(seg => seg !== drop)
    keptButtons = keptButtons.filter(b => b !== drop)
    keptCards = keptCards.filter(b => b !== drop)
  }
  return { segments: keptSegments, buttons: keptButtons, cards: keptCards }
}

// --- コマンドカード（#1963）------------------------------------------------------------------

// （カード, コマンド）の並び。新しいカードから、カードの中はコマンドの順
function cardPairs(items: readonly TakoCard[]): CardPair[] {
  const out: CardPair[] = []
  for (const card of [...items].reverse()) {
    card.commands.forEach((command, i) => out.push({ card, index: i + 1, command }))
  }
  return out
}

// 帯で選んでいるカードのコマンド。tako が描かせない（view.cards が無い）・カードが無い・band.segments に
// card が無いなら null。選択が消えた（閉じた・押し出された）ら新しいカードの 1 件目
function cardSelection(view: TakoView, cursor: { card: number; index: number } | null): CardSel | null {
  const segments: readonly TakoBandSegment[] = view.ui?.band.segments ?? DEFAULT_SEGMENTS
  if (view.cards === undefined || !segments.includes('card')) return null
  const pairs = cardPairs(view.cards.items)
  if (pairs.length === 0) return null
  const found = cursor === null ? -1 : pairs.findIndex(p => p.card.id === cursor.card && p.index === cursor.index)
  const pos = Math.max(0, found)
  const pair = pairs[pos]
  return pair === undefined ? null : { ...pair, pos, pairs }
}

// 帯のカードのボタン（Copy / Run を先に残し、閉じる・次はその後）。ホットキーは tako が選んだもの
function cardButtonsOf(view: TakoView, card: CardSel | null): CardButton[] {
  const keys = view.cards?.hotkeys
  if (card === null || keys === undefined) return []
  const w = words(view.lang)
  const out: CardButton[] = [
    { op: 'copy', label: w.copy, hotkey: keys.copy, rank: 2.5 },
    { op: 'run', label: w.run, hotkey: keys.run, rank: 2.51 },
  ]
  if (card.pairs.length > 1) out.push({ op: 'next', label: w.next, hotkey: keys.next, rank: 2.9 })
  out.push({ op: 'dismiss', label: w.close, hotkey: keys.dismiss, rank: 2.91 })
  return out
}

// 帯のカードが押せる形で収まったか: Copy と Run があり、選べるコマンドが複数なら「次」もある
// （「次」が無いと他のカードへ行けない = そのカードは帯からは押せない）
function cardPressable(cards: readonly CardButton[], card: CardSel): boolean {
  const has = (op: CardOp): boolean => cards.some(b => b.op === op)
  return has('copy') && has('run') && (card.pairs.length === 1 || has('next'))
}

// 直近の描画を控え、変わったら次の報告で tako へ返す
function noteBand(shown: boolean, columns: number | undefined, segments: string[], buttons = 0, bar = false, cards: number[] = []): void {
  const key = JSON.stringify([shown, columns, segments, buttons, bar, cards])
  if (key === lastBandKey) return
  lastBandKey = key
  bandShown = shown
  bandColumns = columns
  bandSegments = segments
  bandButtons = buttons
  bandBar = bar
  bandCards = cards
  dirty = true
}

// 入力欄の下の行にバーを描いたか（#1962）
function noteHint(bar: boolean): void {
  if (bar === hintBar) return
  hintBar = bar
  dirty = true
}

// 使用制限・ctx のバーの文字列（#1962）。描くかは tako が決める（view.usage_bar.draw）。値の無い項目は
// 飛ばし、1 つも無ければ描かない。形は `<ラベル> <棒> <N>%`（tako は画面を読むときにこの形を除く）
function barText(view: TakoView): string | null {
  if (view.band_style === 's3' || view.usage_bar?.draw !== true) return null
  const parts: string[] = []
  for (const item of view.ui?.usage_bar.items ?? ['five_hour', 'seven_day', 'ctx']) {
    const percent = item === 'ctx' ? view.ctx?.percent : view.rate_limits.find(l => l.kind === item)?.percent
    if (percent === undefined) continue
    const p = Math.max(0, Math.min(100, Math.round(percent)))
    parts.push(`${item === 'ctx' ? 'ctx' : limitName(item)} ${BAR_GLYPHS[Math.min(7, Math.floor(p / 12.5))]} ${p}%`)
  }
  return parts.length === 0 ? null : parts.join(' ')
}

// バーの置き場（ui.json が届く前 = 古い tako は既定の prompt_hint）
function barPlace(view: TakoView): 'prompt_hint' | 'band' | 'off' {
  return view.ui?.usage_bar.place ?? 'prompt_hint'
}

// S3（#1881）の描き方（A/B の TAKO_1877_S7_LEGACY）: tako の行の Text 1 本だけを返す（next を包まない）
function drawBandS3($: EngineInterface, e: RenderInput<'AbovePrompt'>, view: TakoView, columns: number): RenderElement {
  const segments = fitBand(segmentsOf(view, true, null), [], columns).segments
  noteBand(true, columns, segments.map(seg => seg.kind))
  const { Text } = $.ui.resolve(e)
  const parts: Array<ReturnType<typeof Text> | string> = []
  segments.forEach((seg, i) => {
    if (i > 0) parts.push(SEP)
    parts.push(seg.tone === 'warning' ? Text({ color: 'warning', children: seg.label }) : seg.label)
  })
  return Text({ dimColor: true, wrap: 'truncate-end', children: parts })
}

// tako の行（#1962）: 区切りの Text とボタンを横に並べて 1 行。幅に合わせて優先度の低いものから落とす。
// 色は ui.json の colors（Claude Code のテーマのキー）。コマンドカード（#1963）は `カード N` の区切りと
// `y: コピー` 等のボタン。押せる形で収まらなければカードは描かない（tako が GPUI の帯へ出す）
function bandRow(
  $: EngineInterface,
  e: RenderInput<'AbovePrompt'>,
  view: TakoView,
  columns: number,
  bar: string | null,
  cursor: { card: number; index: number } | null = null,
  codes: readonly string[] = [],
): RenderElement {
  const s3 = view.ui === undefined
  // #1964: 最新の返答のコードをキーで写す口（会話の行の Copy はクリックでしか押せない）
  const code = codeButtonOf(view, codes)
  const extra = (c: CardSel | null): CardButton[] => (code === null ? cardButtonsOf(view, c) : [...cardButtonsOf(view, c), code])
  let card = cardSelection(view, cursor)
  let fitted = fitBand(segmentsOf(view, s3, bar, card), buttonsOf(view), columns, extra(card))
  if (card !== null && !cardPressable(fitted.cards, card)) {
    card = null
    fitted = fitBand(segmentsOf(view, s3, bar, null), buttonsOf(view), columns, extra(null))
  }
  const kinds = fitted.segments.map(seg => seg.kind)
  if (fitted.cards.some(b => b.op === 'code')) kinds.push('code')
  if (fitted.buttons.length > 0) kinds.push('buttons')
  // 押せる形で描いたカード（「次」で全部へ行ける）= GPUI の帯から外してよいカード
  const claimed = card === null ? [] : (view.cards?.items ?? []).map(c => c.id)
  noteBand(true, columns, kinds, fitted.buttons.length, kinds.includes('usage'), claimed)
  const colors = view.ui?.colors ?? DEFAULT_COLORS
  const { Box, Button, Text } = $.ui.resolve(e)
  const parts: Array<ReturnType<typeof Text> | string> = []
  fitted.segments.forEach((seg, i) => {
    if (i > 0) parts.push(SEP)
    if (seg.tone === 'warning') parts.push(Text({ color: colors.warn, children: seg.label }))
    else if (seg.tone === 'accent') parts.push(Text({ color: colors.accent, children: seg.label }))
    else parts.push(seg.label)
  })
  const line = Text({ color: colors.dim, wrap: 'truncate-end', children: parts })
  const selected = card
  const latest = codes.at(-1)
  const cardButtons = fitted.cards.flatMap(b => {
    if (b.op === 'code') {
      return latest === undefined
        ? []
        : [Button({ key: 'tako-code-latest', label: b.label, hotkey: b.hotkey, plain: true, onPress: press => copyCode($, latest, press) })]
    }
    return selected === null
      ? []
      : [Button({ key: `tako-card-${b.op}`, label: b.label, hotkey: b.hotkey, plain: true, onPress: press => pressCard($, b.op, selected, press) })]
  })
  if (fitted.buttons.length === 0 && cardButtons.length === 0) return line
  const buttons = fitted.buttons.map(b =>
    Button({ key: `tako-button-${b.button.id}`, label: b.button.label, hotkey: b.button.hotkey, onPress: () => pressButton($, b.press) }),
  )
  return Box({ flexDirection: 'row', columnGap: BUTTON_GAP, children: [line, ...cardButtons, ...buttons] })
}

// 他の mod の行（next(e) の答え）を上に、tako の行を下に並べる（#1962 / 設計書 §9.5）。下に誰も
// 居なければ答えはエンジン自身の描画（{ type: 'engine' }。調査票の無い帯は空）なので tako の行だけ
function stackBand($: EngineInterface, e: RenderInput<'AbovePrompt'>, below: RenderElement, row: RenderElement): RenderElement {
  if (below.type === 'engine') return row
  const { Box } = $.ui.resolve(e)
  return Box({ flexDirection: 'column', children: [below, row] })
}

// ボタンを押したとき（#1962）。語彙どおりに実行し、結果（種類と成否だけ）を次の報告で tako へ返す。
// tako / shell は tako が組んだ CLI の引数をそのまま渡す（ここでシェルの文字列は組まない）
async function pressButton($: EngineInterface, press: Press): Promise<void> {
  let ok = false
  try {
    if (press.kind === 'slash') {
      await $.command.run({ command: press.command })
      ok = true
    } else if (press.kind === 'prompt') {
      ok = (await $.prompt.fill({ text: press.text, mode: 'insert' })).isFilled
    } else if (cli !== undefined) {
      const done = await $.process.run([cli, ...press.argv], { timeoutMs: PRESS_TIMEOUT_MS })
      ok = done.exitCode === 0
      if (!ok) $.ui.log(`tako mod: button exit ${done.exitCode}: ${done.stderr.trim().slice(0, 200)}`, { to: 'debug' })
    }
  } catch (err) {
    $.ui.log(`tako mod: button failed: ${String(err).slice(0, 200)}`, { to: 'debug' })
  }
  lastPress = { kind: press.kind, ok, at: await $.clock.now() }
  dirty = true
}

// カードのボタンを押したとき（帯 = #1963・会話の行 = #2159。どちらもここを通る）。Copy は Claude Code の
// $.ui.copy（論理文字列をそのまま）。他の mod の ui.copy フックに拒まれる等で写らなければ tako の CLI
// （show-command --copy = GUI がクリップボードへ書く）へ落とす。Run / 閉じるは tako が組んだ引数をそのまま
// （実行記録はスマホ・GPUI のカードと同じ dispatch が付ける）。「次」は帯の選択を進めるだけ（tako へは何も送らない）。
// Run は同じコマンドの二重押しを捨て（runBusy）、tako に断られたら（実行中の再実行等）理由をトーストで知らせる
async function pressCard($: EngineInterface, op: CardOp, sel: CardSel, press: UiPressArgument): Promise<void> {
  if (op === 'next') {
    const next = sel.pairs[(sel.pos + 1) % sel.pairs.length] ?? sel
    await $.state.set(CARD_CURSOR, { card: next.card.id, index: next.index })
    return
  }
  // #2159: 読みと書きの間に await を挟まない = 同時に届いた 2 打目も必ずこの番に当たる
  const runKey = `${sel.card.id}:${sel.index}`
  if (op === 'run') {
    const now = await $.clock.now()
    if ((runBusy.get(runKey) ?? 0) > now) return
    for (const [key, until] of runBusy) if (until <= now) runBusy.delete(key)
    runBusy.set(runKey, Number.POSITIVE_INFINITY)
  }
  let kind: TakoPress['kind'] = op === 'copy' ? 'card_copy' : op === 'run' ? 'card_run' : 'card_dismiss'
  let ok = false
  let reason = ''
  try {
    if (op === 'copy') {
      const copied = await $.ui.copy({ text: sel.command.text, surface: press.surface })
      ok = copied.isCopied
      if (!copied.isCopied && cli !== undefined) {
        kind = 'card_copy_cli'
        const done = await $.process.run([cli, ...sel.command.copy_args], { timeoutMs: PRESS_TIMEOUT_MS })
        ok = done.exitCode === 0
      }
    } else if (cli !== undefined) {
      const argv = op === 'run' ? sel.command.run_args : sel.card.dismiss_args
      const done = await $.process.run([cli, ...argv], { timeoutMs: PRESS_TIMEOUT_MS })
      ok = done.exitCode === 0
      if (!ok) reason = refusedReason(done.stderr)
    }
    if (!ok) $.ui.log(`tako mod: card ${op} failed`, { to: 'debug' })
  } catch (err) {
    $.ui.log(`tako mod: card ${op} failed: ${String(err).slice(0, 200)}`, { to: 'debug' })
  }
  lastPress = { kind, ok, at: await $.clock.now() }
  if (op === 'run') {
    // 走らせたら少しの間だけ捨てる（ダブルクリックの 2 打目）・断られた / 失敗したらすぐ押し直せる
    if (ok) runBusy.set(runKey, lastPress.at + RUN_REPEAT_MS)
    else runBusy.delete(runKey)
    if (!ok) {
      try {
        $.ui.toast(words(lang).runRefused(reason), { timeoutMs: 5_000 })
      } catch {
        // トーストが出せなくても断られた結果は変わらない（last_press に残る）
      }
    }
  }
  // 実行記録・閉じたことは次の応答（view.cards）で届く
  dirty = true
}

// tako の CLI が断った理由（`error: <理由>` の最後の行。tako の dispatch の文言 = 実行中なら「このコマンドは
// まだ実行中…」）。トーストに収まるよう切る
function refusedReason(stderr: string): string {
  const line = stderr.split('\n').map(l => l.trim()).filter(l => l !== '').at(-1) ?? ''
  return clipCells(line.replace(/^error:\s*/, ''), RUN_REASON_MAX)
}

// tako_show_command の show（action を省いた呼び出しを含む）か
function isShowCall(tool: string, input: unknown): boolean {
  if (!SHOW_TOOL.test(tool)) return false
  const action = typeof input === 'object' && input !== null ? (input as { action?: unknown }).action : undefined
  return action === undefined || action === 'show'
}

// 呼び出しの結果からカードの id を拾う（MCP の content の text に tako の応答の JSON =
// `{"card":{"id":N,…}}`）。形は Claude Code の版で揺れうるので、文字列・配列・{ text } / { content } を辿る
function cardIdOf(output: unknown, depth = 0): number | undefined {
  if (depth > 4 || output === null || output === undefined) return undefined
  if (typeof output === 'string') {
    try {
      return cardIdOf(JSON.parse(output) as unknown, depth + 1)
    } catch {
      return undefined
    }
  }
  if (Array.isArray(output)) {
    for (const item of output) {
      const id = cardIdOf(item, depth + 1)
      if (id !== undefined) return id
    }
    return undefined
  }
  if (typeof output !== 'object') return undefined
  const o = output as { card?: unknown; text?: unknown; content?: unknown }
  if (typeof o.card === 'object' && o.card !== null) {
    const id = (o.card as { id?: unknown }).id
    if (typeof id === 'number') return id
  }
  return cardIdOf(o.text, depth + 1) ?? cardIdOf(o.content, depth + 1)
}

// 呼び出しの引数（モデルが送った形）のコマンドとラベル。カードがもう store に無い（閉じた）ときの表示用
function callCommands(input: unknown): { commands: string[]; label?: string } {
  const o = typeof input === 'object' && input !== null ? (input as { commands?: unknown; label?: unknown }) : {}
  const commands = Array.isArray(o.commands) ? o.commands.filter((c): c is string => typeof c === 'string') : []
  return { commands, label: typeof o.label === 'string' && o.label !== '' ? o.label : undefined }
}

// 会話の行のカード（#1963）: 見出し（tako・カード N・ラベル）・コマンドを Code で（見た目だけ折り返す。
// 写すのはボタン = 論理文字列）・実行記録・押す案内。クリックが届く（#2159: tako がクリックを渡す = view.cards.click
// ∧ 全画面の端末）ならコマンドごとに `[ 実行 ]` / `[ コピー ]`（クリック 1 回。帯と同じ pressCard）を置き、
// 届かなければ帯で押す案内だけ（押せないボタンを見せない）。カードが store に無い（閉じた・押し出された）
// なら引数から描いて「閉じた」と添える。下の他の mod が描いていればその下に足す（next の答えを包む）
function drawCardRow($: EngineInterface, e: RenderInput<'ToolUse'>, view: TakoView, below: RenderElement): RenderElement {
  const w = words(view.lang)
  const colors = view.ui?.colors ?? DEFAULT_COLORS
  const id = cardIdOf(e.props.output)
  const card = id === undefined ? undefined : view.cards?.items.find(c => c.id === id)
  const call = callCommands(e.props.input)
  const commands: Array<{ text: string; run?: TakoCardCommand['run'] }> =
    card === undefined ? call.commands.map(text => ({ text })) : card.commands
  const label = card === undefined ? call.label : card.label
  const clickable = card !== undefined && view.cards?.click === true && e.surface === 'terminal' && e.viewport?.isFullscreen === true
  const { Box, Button, Code, Text } = $.ui.resolve(e)
  const title: Array<ReturnType<typeof Text> | string> = [Text({ color: colors.accent, bold: true, children: 'tako' })]
  if (id !== undefined) title.push('  ', Text({ bold: true, children: w.card(id) }))
  if (label !== undefined) title.push(`  ${label}`)
  if (id !== undefined && card === undefined && !e.props.isRunning) title.push(Text({ color: colors.dim, children: `  ${w.cardClosed}` }))
  const rows: RenderElement[] = [Text({ wrap: 'wrap', children: title })]
  commands.forEach((command, i) => {
    const code = Code({ source: command.text, language: 'bash', wrap: 'wrap' })
    rows.push(
      commands.length > 1
        ? Box({ flexDirection: 'row', children: [Text({ color: colors.dim, children: `${i + 1} ` }), Box({ flexGrow: 1, flexShrink: 1, children: [code] })] })
        : code,
    )
    const state =
      command.run === undefined
        ? null
        : Text({
            color: command.run.state === 'running' ? colors.accent : command.run.exit_code === 0 ? 'success' : command.run.state === 'exited' ? 'error' : colors.dim,
            children: w.runState(command.run),
          })
    const pair = card === undefined ? undefined : card.commands[i]
    if (clickable && card !== undefined && pair !== undefined) {
      // key はカード id と番号で固定（描き直しで mount し直さない = Claude Code が描いた直後 300 ms のクリックを
      // 捨てる窓を作り直さない）。押した後の流れは帯のボタンと同じ pressCard（Run は tako が組んだ run_args）
      const sel: CardSel = { card, index: i + 1, command: pair, pos: 0, pairs: [{ card, index: i + 1, command: pair }] }
      const buttons: RenderElement[] = [
        Button({ key: `tako-card-${card.id}-${i + 1}-run`, label: w.run, variant: 'primary', onPress: press => pressCard($, 'run', sel, press) }),
        Button({ key: `tako-card-${card.id}-${i + 1}-copy`, label: w.copy, onPress: press => pressCard($, 'copy', sel, press) }),
      ]
      if (state !== null) buttons.push(state)
      rows.push(Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 1, children: buttons }))
    } else if (state !== null) {
      rows.push(state)
    }
  })
  if (card !== undefined && view.cards !== undefined) {
    const hint = clickable ? w.cardKeyHint : w.cardHint
    rows.push(Text({ color: colors.dim, wrap: 'wrap', children: hint(view.cards.hotkeys.copy, view.cards.hotkeys.run) }))
  }
  const box = Box({ flexDirection: 'column', borderStyle: 'round', borderColor: colors.accent, paddingX: 1, children: rows })
  if (below.type === 'engine') return box
  return Box({ flexDirection: 'column', children: [below, box] })
}

// --- チャット風の描画（#1964）------------------------------------------------------------------

/** 囲みのコードブロック 1 つ（言語と論理文字列） */
type CodeBlock = { lang: string; source: string }

// Markdown の囲みのコードブロック（``` / ~~~。3 字以上・行頭の空白 3 字まで）を順に取り出す。中身は
// 論理文字列のまま（画面の折り返しは混ざらない = Copy に渡すのはこれ）。閉じていないブロック（生成中）は数えない
function codeBlocks(text: string): CodeBlock[] {
  const out: CodeBlock[] = []
  let open: { fence: string; lang: string; body: string[] } | null = null
  for (const line of text.split('\n')) {
    if (open === null) {
      const m = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line)
      if (m === null) continue
      const fence = m[1] ?? ''
      const info = (m[2] ?? '').trim()
      // ``` の情報文字列に ` は入らない（CommonMark）= それはコードブロックではない
      if (fence.startsWith('`') && info.includes('`')) continue
      open = { fence, lang: info.split(/\s+/)[0] ?? '', body: [] }
      continue
    }
    const fence: string = open.fence
    const trimmed = line.replace(/^ {0,3}/, '').trimEnd()
    if (trimmed.length >= fence.length && trimmed === (fence[0] ?? '').repeat(trimmed.length)) {
      out.push({ lang: open.lang, source: open.body.join('\n') })
      open = null
    } else {
      open.body.push(line)
    }
  }
  return out
}

// コードを写す（#1964）。$.ui.copy（論理文字列そのまま）。他の mod の ui.copy フックに拒まれたら、その mod の
// 選択を尊重して写さず、トーストで知らせる（カードと違い tako の store に無い文字列なので CLI へは落とさない）
async function copyCode($: EngineInterface, text: string, press: UiPressArgument): Promise<void> {
  let ok = false
  try {
    ok = (await $.ui.copy({ text, surface: press.surface })).isCopied
  } catch (err) {
    $.ui.log(`tako mod: code copy failed: ${String(err).slice(0, 200)}`, { to: 'debug' })
  }
  const w = words(lang)
  try {
    $.ui.toast(ok ? w.copied : w.copyRefused, { timeoutMs: 3_000 })
  } catch {
    // トーストが出せなくても写した結果は変わらない
  }
  lastPress = { kind: 'code_copy', ok, at: await $.clock.now() }
  dirty = true
}

// 利用者の発話を右寄せの吹き出しに（#1964）。エンジンの行（{ type: 'engine' }）なら本文を Text で描き直し、
// 他の mod が描いていればその描画を吹き出しの中に包む（next(e) の答えを捨てない）
function drawBubble($: EngineInterface, e: RenderInput<'UserMessage'>, view: TakoView, below: RenderElement): RenderElement {
  const colors = view.ui?.colors ?? DEFAULT_COLORS
  const { Box, Text } = $.ui.resolve(e)
  const inner = below.type === 'engine' ? Text({ wrap: 'wrap', children: e.props.text }) : below
  const columns = e.viewport?.columns ?? 80
  return Box({
    flexDirection: 'row',
    justifyContent: 'flex-end',
    paddingLeft: Math.max(BUBBLE_INDENT_MIN, Math.floor(columns / 5)),
    children: [Box({ borderStyle: 'round', borderColor: colors.accent, paddingX: 1, flexShrink: 1, children: [inner] })],
  })
}

// AI の返答の下にコードブロックごとの Copy（#1964。クリックで押す。key は返答の id と順番で固定 = 描き直しで
// mount し直さない = Claude Code が描いた直後 300 ms のクリックを捨てる窓を作り直さない）
function drawCodeCopy(
  $: EngineInterface,
  e: RenderInput<'AssistantMessage'>,
  view: TakoView,
  below: RenderElement,
  blocks: readonly CodeBlock[],
): RenderElement {
  const w = words(view.lang)
  const { Box, Button } = $.ui.resolve(e)
  const buttons = blocks.map((block, i) =>
    Button({
      key: `tako-code-${e.requestId}-${i}`,
      label: w.copyCode(i + 1, blocks.length, block.lang),
      onPress: press => copyCode($, block.source, press),
    }),
  )
  const copies = Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 1, paddingLeft: 2, children: buttons })
  return Box({ flexDirection: 'column', children: [below, copies] })
}

// 帯の「最新のコードをコピー」（#1964）。view.chat.code_copy が真で、最新の返答にコードブロックがあるときだけ。
// 優先度はカスタムボタンより低い（幅が足りなければ先に落とす。会話の行の Copy はクリックで押せる）
function codeButtonOf(view: TakoView, codes: readonly string[]): CardButton | null {
  const chat = view.chat
  if (chat === undefined || !chat.code_copy || codes.length === 0 || view.band_style === 's3') return null
  return { op: 'code', label: words(view.lang).latestCode(codes.length), hotkey: chat.hotkey, rank: 3.5 }
}

// ツールの名前（MCP の `mcp__<登録名>__<名前>` は `<登録名>.<名前>`）
function toolName(tool: string): string {
  const m = /^mcp__(.+?)__(.+)$/.exec(tool)
  return m === null ? tool : `${m[1]}.${m[2]}`
}

// ツールの要約の中身（何に対しての呼び出しか。1 行目だけ）。よく使うツールは決まったキー、他は最初の文字列
function toolSubject(tool: string, input: unknown): string {
  const o = typeof input === 'object' && input !== null ? (input as Record<string, unknown>) : {}
  const pick = (...keys: string[]): string | undefined => {
    for (const key of keys) {
      const v = o[key]
      if (typeof v === 'string' && v.trim() !== '') return v
    }
    return undefined
  }
  let text: string | undefined
  if (tool === 'Bash') text = pick('command')
  else if (tool === 'Read' || tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit') text = pick('file_path')
  else if (tool === 'NotebookEdit') text = pick('notebook_path')
  else if (tool === 'Grep' || tool === 'Glob') text = pick('pattern')
  else if (tool === 'WebFetch') text = pick('url')
  else if (tool === 'WebSearch') text = pick('query')
  else if (tool === 'Task' || tool === 'Agent') text = pick('description', 'prompt')
  else if (tool === 'TodoWrite' && Array.isArray(o.todos)) text = `${o.todos.length} todos`
  if (text === undefined) {
    for (const v of Object.values(o)) {
      if (typeof v === 'string' && v.trim() !== '') {
        text = v
        break
      }
    }
  }
  return (text ?? '').trim().split('\n')[0] ?? ''
}

// ツールの呼び出しの 1 行の要約（#1964）: 名前・何に対してか・状態・「詳細」/「閉じる」（クリックで押す）
function toolSummaryRow($: EngineInterface, e: RenderInput<'ToolUse'>, view: TakoView, open: boolean): RenderElement {
  const w = words(view.lang)
  const colors = view.ui?.colors ?? DEFAULT_COLORS
  const { Box, Button, Text } = $.ui.resolve(e)
  const p = e.props
  const state = p.isRunning ? w.toolRunning : p.isInterrupted ? w.toolInterrupted : p.isErrored ? w.toolError : w.toolDone
  const tone = p.isRunning ? colors.accent : p.isErrored || p.isInterrupted ? 'error' : 'success'
  return Box({
    flexDirection: 'row',
    columnGap: 1,
    paddingLeft: 2,
    children: [
      Text({ color: colors.accent, bold: true, children: toolName(p.tool) }),
      Box({ flexGrow: 1, flexShrink: 1, children: [Text({ color: colors.dim, wrap: 'truncate-end', children: toolSubject(p.tool, p.input) })] }),
      Text({ color: tone, children: state }),
      Button({ key: `tako-tool-${p.tool_use_id}`, label: open ? w.toolHide : w.toolDetails, plain: true, dimColor: true, onPress: () => toggleTool($, p.tool_use_id) }),
    ],
  })
}

// ツールの行（#1964）: エンジンの行なら 1 行の要約に置き換え、他の mod が描いていればその下に要約を足す。
// 「詳細」で開いた呼び出しは要約の下に next の答え（エンジンの行 = 出力つき）を戻す
function drawToolSummary(
  $: EngineInterface,
  e: RenderInput<'ToolUse'>,
  view: TakoView,
  below: RenderElement,
  open: boolean,
): RenderElement {
  const row = toolSummaryRow($, e, view, open)
  if (!open && below.type === 'engine') return row
  const { Box } = $.ui.resolve(e)
  return Box({ flexDirection: 'column', children: open ? [row, below] : [below, row] })
}

// 「詳細」/「閉じる」: 開いた呼び出しはエンジンの行（出力つき）を要約の下に戻す（$.state = 描き直しが購読する）
async function toggleTool($: EngineInterface, id: string): Promise<void> {
  const open = (await $.state.get(TOOL_OPEN)).value ?? []
  const next = open.includes(id) ? open.filter(x => x !== id) : [...open, id].slice(-TOOL_OPEN_MAX)
  await $.state.set(TOOL_OPEN, next)
}

// 応答の view.chat を取り込む（#1964）。組が変わったら次の報告の renders.chat で tako へ返す
function absorbChat(view: TakoView | null): void {
  const next = view === null || view.band_style === 's3' ? undefined : view.chat
  if (JSON.stringify(next) === JSON.stringify(chatView)) return
  chatView = next
  dirty = true
}

// 最新の返答のコードブロックを控える（#1964。帯の「最新のコードをコピー」。サブエージェントのターンは数えない）
async function noteAnswer($: EngineInterface, answer: string): Promise<void> {
  try {
    await $.state.set(CHAT_CODES, codeBlocks(answer).map(b => b.source))
  } catch (err) {
    $.ui.log(`tako mod: chat codes unwritable: ${String(err).slice(0, 200)}`, { to: 'debug' })
  }
}

// 残り時間（リセットまで）。端末の時刻帯に依らない書き方にする
function untilText(ms: number): string {
  const minutes = Math.max(0, Math.round(ms / 60_000))
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  const mins = minutes % 60
  if (days > 0) return `${days}d${hours}h`
  if (hours > 0) return `${hours}h${mins}m`
  return `${mins}m`
}

type SavedBand = { hidden: boolean; at: number }

function savedBand(value: unknown): SavedBand | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const v = value as { hidden?: unknown; at?: unknown }
  if (typeof v.hidden !== 'boolean' || typeof v.at !== 'number') return undefined
  return { hidden: v.hidden, at: v.at }
}

// tako の材料を $.state へ（同じなら書かない）
async function setView($: EngineInterface, view: TakoView | null): Promise<void> {
  // 材料が消えた（tako が応答しない・休眠）ならチャットも描かない = renders.chat を引っ込める（#1964）
  if (view === null) absorbChat(null)
  const json = JSON.stringify(view)
  if (json === lastViewJson) return
  lastViewJson = json
  await $.state.set(VIEW, view)
}

// トグルを変える（$.store はこの読み込み元の写し。正本の ui.json へは報告の toggled_at で渡る = #1960。
// $.state は描画の購読のための写し）
async function setHidden($: EngineInterface, hidden: boolean, at: number): Promise<void> {
  bandToggledAt = at
  if (hidden !== bandHidden) {
    bandHidden = hidden
    dirty = true
  }
  await $.store.set(BAND_KEY, { hidden, at })
  await $.state.set(HIDDEN, hidden)
}

// $.store を読み直す（同じ設定 dir の別のセッションが切り替えたぶんを拾う）。
// 読めなくても報告は続ける（帯のトグルが前の値のままになるだけ）
async function syncStore($: EngineInterface): Promise<void> {
  let stored: unknown
  try {
    stored = await $.store.get(BAND_KEY)
  } catch {
    return
  }
  const saved = savedBand(stored)
  if (saved === undefined || (bandToggledAt !== undefined && saved.at <= bandToggledAt)) return
  bandToggledAt = saved.at
  if (saved.hidden !== bandHidden) {
    bandHidden = saved.hidden
    dirty = true
  }
  await $.state.set(HIDDEN, saved.hidden)
}

// サイドバーのボタン。押した時点のトグルを反転する（描いた時点の値は使わない）
async function toggleBand($: EngineInterface): Promise<void> {
  await setHidden($, !bandHidden, await $.clock.now())
}

// `tako mod report` の応答を取り込む。view が無い（S3 の A/B・古い tako）なら何も描かない
async function absorb($: EngineInterface, stdout: string): Promise<void> {
  let view: TakoView | null = null
  try {
    const reply = JSON.parse(stdout) as { tako?: { view?: TakoView | null } }
    view = reply.tako?.view ?? null
  } catch {
    view = null
  }
  if (view !== null) {
    viewAt = await $.clock.now()
    lang = view.lang
    const style = view.band_style === 's3' ? 's3' : undefined
    if (style !== lastStyle) {
      lastStyle = style
      dirty = true
    }
    if (commandLang !== lang) {
      try {
        await registerCommand($)
      } catch {
        // 説明文が前の言語のままになるだけ
      }
    }
    const request = view.band_request
    if (request !== undefined && request.at > (bandToggledAt ?? 0)) {
      await setHidden($, request.hidden, request.at)
    }
  }
  await absorbCards($, view)
  absorbChat(view)
  await setView($, view)
}

// 応答のカードを取り込む（#1963）: tako が描かせるか（renders.cards を送るか）と、新しいカードが来たら
// 帯の選択をその 1 件目へ移す（AI が出したばかりのカードをすぐ押せるように）
async function absorbCards($: EngineInterface, view: TakoView | null): Promise<void> {
  const offered = view?.cards !== undefined && view.band_style !== 's3'
  if (offered !== cardsOffered) {
    cardsOffered = offered
    dirty = true
  }
  const newest = view?.cards?.items.at(-1)?.id
  if (newest === undefined || newest === newestCard) return
  newestCard = newest
  try {
    await $.state.set(CARD_CURSOR, { card: newest, index: 1 })
  } catch (err) {
    $.ui.log(`tako mod: card cursor unwritable: ${String(err).slice(0, 200)}`, { to: 'debug' })
  }
}

export const register: Register = on => {
  // 送信時の確認（#2050）: 人の入力だけを送る前に tako へ判定させる。壊れても送信を止めない
  on('prompt.submit', async ($, e, next) => {
    if (GUARD_ORIGINS.includes(e.origin.kind) && (await guardPrompt($, e.text)) === 'drop') {
      return { drop: words(lang).guardDropped }
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await wake($)
    return started
  }).catch(($, e, next) => next(e))

  on('turn.start', ($, e, next) => {
    turn = 'busy'
    pendingTool = undefined
    dirty = true
    return next(e)
  }).catch(($, e, next) => next(e))

  // effort は各ステップの turn.step が運ぶ（関数フックなので classic 系が届かない組織アカウントでも
  // 来る = FR-2.42.7 で欠けていた effort を埋める。#1880）。サブエージェントのステップは数えない。
  // turn.step はモデルの出力を流すストリームのフック: 値を控えたら `yield*` で**そのまま素通し**し、
  // チャンクには触らない（壊れても .catch が素通しへ戻す）
  on('turn.step', async function* ($, e, next) {
    const step = e as unknown as { effort?: unknown; agentId?: unknown }
    const level = effortLevel(step.effort)
    if (step.agentId === undefined && level !== undefined && level !== effort) {
      effort = level
      dirty = true
    }
    return yield* next(e)
  }).catch(async function* ($, e, next) {
    return yield* next(e)
  })

  // classic 系が届くかの印（すべてのツール呼び出しで tool.check より先に来る）
  on('classic.PreToolUse', ($, e, next) => {
    classicEvents = true
    return next(e)
  }).catch(($, e, next) => next(e))

  // ダイアログの表示と同時に来る（設計書 §1.3）。AskUserQuestion もここを通るのでツール名で分ける
  on('classic.PermissionRequest', ($, e, next) => {
    classicEvents = true
    turn = e.tool_name === 'AskUserQuestion' ? 'question' : 'permission'
    pendingTool = e.tool_name
    if (e.effort !== undefined) effort = e.effort.level
    dirty = true
    return next(e)
  }).catch(($, e, next) => next(e))

  // classic 系が届かない環境の代わりの手がかり。判定が ask でも auto モードは分類器が黙って
  // 通しうるので、**ダイアログが確かに出るものだけ**を拾う: ask ルールに当たった呼び出し
  // （auto モードより優先される）と、人に計画の承認を求める ExitPlanMode
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (!classicEvents && verdict.decision === 'ask' && (verdict.rule !== undefined || e.tool === 'ExitPlanMode')) {
      turn = 'permission'
      pendingTool = e.tool
      dirty = true
    }
    return verdict
  }).catch(($, e, next) => next(e))

  // 承認・拒否・回答の瞬間を知らせるイベントは無いので、そのツールの呼び出しが返ったところで戻す。
  // AskUserQuestion は呼び出しの開始と同時に質問が出る（classic 系が届かなくても分かる）
  on('tool.call', async ($, e, next) => {
    if (e.tool === 'AskUserQuestion') {
      turn = 'question'
      pendingTool = e.tool
      dirty = true
    }
    const result = await next(e)
    if ((turn === 'permission' || turn === 'question') && e.tool === pendingTool) {
      turn = 'busy'
      pendingTool = undefined
      dirty = true
    }
    // #1963: カードが増えた / 減った = すぐ報告して応答の view.cards を取りに行く（heartbeat の 15 秒を待たない）
    if (SHOW_TOOL.test(e.tool)) dirty = true
    return result
  }).catch(($, e, next) => next(e))

  // サブエージェントのターン（agentId あり）は数えない（#1021 の isSidechain 除外と同じ理由）
  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (e.agentId === undefined) {
      turn = 'idle'
      pendingTool = undefined
      lastTurn = { duration_ms: e.durationMs, reason: e.reason }
      dirty = true
      // #1964: 帯の「最新のコードをコピー」の材料（本文は $.state に置くだけで報告には載せない）
      if (cli !== undefined) await noteAnswer($, e.answer)
    }
    return done
  }).catch(($, e, next) => next(e))

  // 会話の行が足された（#1964）: 本筋（サブエージェントでない）の user / assistant の行を数える。GPUI の
  // チャットが表に出ているペイン（view.chat.notify）ではすぐ報告する = transcript を通知で読み直す。
  // 数えるのは next(e) の後（= transcript に書かれた後）
  on('session.append', async ($, e, next) => {
    const done = await next(e)
    if (e.agentId === undefined && (e.message.type === 'user' || e.message.type === 'assistant')) {
      chatSeq += 1
      if (chatView?.notify === true) dirty = true
    }
    return done
  }).catch(($, e, next) => next(e))

  // effort はターンの終わりの Stop が運ぶ（effort を持たないモデルでは来ない）
  on('classic.Stop', ($, e, next) => {
    if (e.effort !== undefined && e.effort.level !== effort) {
      effort = e.effort.level
      dirty = true
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  // /clear と /resume は同じプロセスで別のセッションが続く（session.start は来ない）。
  // 次の報告が新しい session_id を運ぶので、状態だけ戻して報告は続ける
  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear' || e.reason === 'resume') {
      turn = 'idle'
      pendingTool = undefined
      lastTurn = undefined
      dirty = true
      // 前の会話のコードを帯から外す（#1964）
      if (cli !== undefined) await noteAnswer($, '')
      return next(e)
    }
    await finish($)
    return next(e)
  }).catch(($, e, next) => next(e))

  // 帯（プロンプトの上）。他の mod の行（next(e) の答え）を必ず包み、その下に tako の行を 1 行（#1962）。
  // tako の外・材料が無い（古い）・隠している・調査票が使っているときは下へ譲るだけ。
  // 権限ダイアログ・質問の表示中はそもそも Claude Code が帯を出さない
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!bandHookSeen) {
      bandHookSeen = true
      dirty = true
    }
    const view = (await $.state.get(VIEW)).value ?? null
    const hidden = (await $.state.get(HIDDEN)).value ?? false
    const columns = e.props.bodyColumns
    if (cli === undefined || view === null || hidden || e.props.hasSurvey) {
      noteBand(false, columns, [])
      return next(e)
    }
    // A/B（TAKO_1877_S7_LEGACY）: S3 の描き方 = tako の行だけを返す
    if (view.band_style === 's3') return drawBandS3($, e, view, columns)
    const below = await next(e)
    const bar = barPlace(view) === 'band' ? barText(view) : null
    const cursor = (await $.state.get(CARD_CURSOR)).value ?? null
    const codes = view.chat?.code_copy === true ? ((await $.state.get(CHAT_CODES)).value ?? []) : []
    return stackBand($, e, below, bandRow($, e, view, columns, bar, cursor, codes))
  }).catch(($, e, next) => next(e))

  // 会話の行（#1963）: tako_show_command の呼び出しを含むグループ（「Called tako」の 1 行）を展開する
  // = その呼び出しが ToolUse の行になり、下のフックがカードに描き替える。#1964: ツールの要約を描くなら
  // どのグループも展開する（1 呼び出し 1 行の要約になる）。展開は isExpanded を書き換えて next へ流すだけ
  // （グループの描画はエンジン / 他の mod のまま）。tako が描かせないときは触らない
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    if (e.props.isExpanded) return next(e)
    const view = cli === undefined ? null : ((await $.state.get(VIEW)).value ?? null)
    if (view === null) return next(e)
    const card = view.cards !== undefined && e.props.calls.some(call => isShowCall(call.tool, call.input))
    const summary = view.chat?.tool_summary === true && view.band_style !== 's3'
    if (!card && !summary) return next(e)
    return next({ ...e, props: { ...e.props, isExpanded: true } })
  }).catch(($, e, next) => next(e))

  // tako_show_command の行をカードに描き替える（#1963）。#1964: それ以外の呼び出しはツールの要約を描くなら
  // 1 行の要約に（「詳細」で開いた呼び出しは要約の下にエンジンの行を戻す）。他の mod が描いていればその下に足す
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    const view = cli === undefined ? null : ((await $.state.get(VIEW)).value ?? null)
    if (view === null) return next(e)
    const show = isShowCall(e.props.tool, e.props.input) && !e.props.isErrored && !e.props.isInterrupted
    if (show && view.cards !== undefined) {
      const below = await next(e)
      return drawCardRow($, e, view, below)
    }
    if (view.chat?.tool_summary !== true || view.band_style === 's3') return next(e)
    const open = ((await $.state.get(TOOL_OPEN)).value ?? []).includes(e.props.tool_use_id)
    const below = await next(e)
    return drawToolSummary($, e, view, below, open)
  }).catch(($, e, next) => next(e))

  // 利用者の発話を吹き出しに（#1964）。tako が描かせない・人の入力でない（通知・他のエージェントの発話）は触らない
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    const view = cli === undefined ? null : ((await $.state.get(VIEW)).value ?? null)
    if (view?.chat?.bubble !== true || view.band_style === 's3' || !BUBBLE_ORIGINS.includes(e.props.origin.kind)) return next(e)
    const below = await next(e)
    return drawBubble($, e, view, below)
  }).catch(($, e, next) => next(e))

  // AI の返答のコードブロックの下に Copy（#1964）。要約の行（isSummary）・コードの無い返答は触らない
  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    const view = cli === undefined ? null : ((await $.state.get(VIEW)).value ?? null)
    if (view?.chat?.code_copy !== true || view.band_style === 's3' || e.props.isSummary === true) return next(e)
    const blocks = codeBlocks(e.props.text)
    if (blocks.length === 0) return next(e)
    const below = await next(e)
    return drawCodeCopy($, e, view, below, blocks)
  }).catch(($, e, next) => next(e))

  // 入力欄の下の行（#1962）: 末尾（tail）に使用制限・ctx のバー。描くかは tako（view.usage_bar）。
  // 行そのもの（hint）は書き換えず、他の mod が足した tail の後ろへ足して必ず next へ流す。
  // tail を描くのは端末だけ（desktop は描かない = 描いたと報告しない）
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    if (!hintHookSeen) {
      hintHookSeen = true
      dirty = true
    }
    const view = (await $.state.get(VIEW)).value ?? null
    const bar = cli === undefined || view === null || e.surface !== 'terminal' || barPlace(view) !== 'prompt_hint' ? null : barText(view)
    noteHint(bar !== null)
    if (bar === null) return next(e)
    const tail = e.props.tail === undefined || e.props.tail === '' ? bar : `${e.props.tail} · ${bar}`
    return next({ ...e, props: { ...e.props, tail } })
  }).catch(($, e, next) => next(e))

  // `/tako` のサイドバー（詳細）
  on('ui.render', { component: 'Pane', requestId: PANE_ID }, async ($, e, next) => {
    const view = (await $.state.get(VIEW)).value ?? null
    const hidden = (await $.state.get(HIDDEN)).value ?? false
    const w = words(view?.lang ?? lang)
    const { Box, Button, Text } = $.ui.resolve(e)
    const toggle = Button({
      key: 'band-toggle',
      label: hidden ? w.show : w.hide,
      onPress: () => toggleBand($),
    })
    if (view === null) {
      return Box({ flexDirection: 'column', children: [Text({ dimColor: true, children: w.noView }), toggle] })
    }
    const now = await $.clock.now()
    const rows: Array<ReturnType<typeof Text>> = []
    const name = view.pane_title ?? `pane ${view.pane}`
    rows.push(Text({ bold: true, wrap: 'truncate-end', children: name }))
    if (view.tab_title !== undefined) rows.push(Text({ dimColor: true, wrap: 'truncate-end', children: `${w.tab} ${view.tab_title}` }))
    const ctx = view.ctx
    rows.push(
      Text({
        children:
          ctx?.percent === undefined
            ? `ctx - (${w.ctxPending})`
            : `ctx ${ctx.percent}% (${ctx.tokens ?? '-'} / ${ctx.window})`,
      }),
    )
    for (const limit of view.rate_limits) {
      const reset = limit.resets_at === undefined ? '' : `  ${w.resetsIn(untilText(limit.resets_at * 1000 - now))}`
      const line = `${limitName(limit.kind)} ${Math.round(limit.percent)}%${reset}`
      rows.push(limit.percent >= view.thresholds.limit_percent ? Text({ color: 'warning', children: line }) : Text({ children: line }))
    }
    rows.push(
      Text({
        bold: true,
        children:
          view.worker_count === 0 ? w.noWorkers : `${w.workers(view.worker_count)}  ${w.attention(view.attention)}`,
      }),
    )
    for (const worker of view.workers) {
      const line = `${worker.attention === undefined ? '  ' : '! '}${worker.name}  ${w.state(worker)}`
      rows.push(
        worker.attention === undefined
          ? Text({ wrap: 'truncate-end', children: line })
          : Text({ color: 'warning', wrap: 'truncate-end', children: line }),
      )
    }
    if (view.worker_count > view.workers.length) {
      rows.push(Text({ dimColor: true, children: w.more(view.worker_count - view.workers.length) }))
    }
    rows.push(Text({ dimColor: true, children: w.thresholds(view.thresholds.ctx_percent, view.thresholds.limit_percent) }))
    return Box({ flexDirection: 'column', children: [...rows, toggle] })
  }).catch(($, e, next) => next(e))

  // `/tako`（サイドバーを開く）・`/tako band on|off`（帯のトグル）。tako の外では登録していない。
  // 出力の行には Claude Code がプラグイン名（tako:）を前置するので、文言には付けない。
  // 出力の行はモデルも読むので短くする（サイドバーを開いたときは何も出さない）
  on('command.run', { command: 'tako' }, async ($, e, next) => {
    if (cli === undefined) return next(e)
    const w = words(lang)
    const args = (typeof e.args === 'string' ? e.args : '').trim().split(/\s+/).filter(arg => arg !== '')
    if (args[0] === 'band' && (args[1] === undefined || args[1] === 'on' || args[1] === 'off') && args.length <= 2) {
      const want = args[1] === 'on' ? false : args[1] === 'off' ? true : !bandHidden
      await setHidden($, want, await $.clock.now())
      return { text: want ? w.hidden : w.shown }
    }
    if (args.length > 0) return { text: w.usage }
    const opened = await $.ui.open({ id: PANE_ID, title: 'tako' })
    return opened.isPlaced ? {} : { text: w.notPlaced(opened.reason) }
  }).catch(($, e, next) => next(e))
}

