// tako mod が tako へ送る報告の契約（#1879。設計書 .agent/plans/2026-10-tako-mod.md §4.2）と、
// tako が応答で返す帯・サイドバーの材料（#1881。§7 S3）・定型の UI 設定（#1960。§9.7）・描いたもの（#1962）・
// コマンドカード（#1963。§9.3）・チャット風の描画（#1964。§9.3）、mod の $.state の契約。
// 受け手 / 送り手の正本は tako_core::claude_mod::{ModReport, ModBand, ModRenders, BandView} と tako_core::claude_mod_ui::UiConfig。
// キーを増やすときは両方を同じコミットで直す。
//
// **会話の本文・プロンプト・ツールの引数は載せない**（AGENTS.md の絶対ルール）。
// pending_tool はツール名だけ。番犬 crates/tako-control/tests/issue1879_claude_mod_watchdog.rs が
// 本文系のキーが紛れ込んでいないかを走査する。

/** ターンの状態。permission = 権限ダイアログ表示中、question = AskUserQuestion 表示中 */
export type TakoTurn = 'idle' | 'busy' | 'permission' | 'question'

export type TakoContext = {
  /** 最初の API 応答までは欠ける（0 埋めしない = 未観測） */
  tokens?: number
  window: number
  percent?: number
}

export type TakoRateLimit = {
  /** five_hour / seven_day / ゲートウェイの spend_limit など */
  kind: string
  percent_used: number
  resets_at?: string
  /**
   * この値を観測した時刻（epoch ms）。% か resets_at が変わったときだけ打ち直す（heartbeat では
   * 前の時刻のまま = #1903）。tako はアカウント単位の値を束ねるときに新しい方を採る
   */
  observed_at: number
}

/** $.state の limitsSeen（窓の種類 → 最後に値が変わった観測）。ホットリロードをまたいで残す */
export type TakoLimitsSeen = Record<string, { percent_used: number; resets_at?: string; observed_at: number }>

export type TakoModReport = {
  schema: 1
  mod_version: string
  claude_version?: string
  session_id?: string
  /** 報告を組んだ時刻（epoch ms） */
  at: number
  model?: string
  effort?: string
  context?: TakoContext
  rate_limits: TakoRateLimit[]
  cost_usd?: number
  turn: TakoTurn
  pending_tool?: string
  last_turn?: { duration_ms: number; reason: string }
  /**
   * classic 系のイベント（PermissionRequest 等）がこのセッションの mod へ届いているか。
   * false のとき permission は ask ルール由来と ExitPlanMode だけ（ルールの無い ask は拾わない）
   */
  classic_events: boolean
  /** CLAUDE_CONFIG_DIR（使用制限はアカウント単位なので束ねる鍵にする。ログには出さない） */
  config_dir?: string
  /** 帯の状態（#1881。描いた文字列は載せない = 区切りの種類だけ） */
  band?: TakoBand
  /**
   * 休眠に入った理由（#1959）。user_disabled = 利用者が Claude Code の /plugin で tako@skills-dir を
   * 止めた（env の注入で読まれていても従う）。これを最後に mod は報告を止める
   */
  dormant?: 'user_disabled'
  /**
   * 利用者の Claude Code に statusLine が設定されているか（#1962。$.settings.read() の statusLine の
   * 有無だけで中身は載せない。読めなければ欠ける）。tako は画面の読み取りと合わせてバーを描くか決める
   */
  status_line?: boolean
  /** 描いているもの（#1962。無い = 何も描いていない = S7-3 前の mod・A/B の S3 の描き方） */
  renders?: TakoRenders
  /** 最後に押されたボタン（#1962。種類と成否だけ） */
  last_press?: TakoPress
  /**
   * 会話の行が足された回数（#1964。起きてからの session.append のうち本筋 = サブエージェントでない
   * user / assistant の行。**数だけ**で本文・uuid は載せない）。GPUI のチャットはこれが変わったときだけ
   * transcript を読み直す（renders.chat.notify が真のとき）
   */
  chat_seq?: number
  /** session.end を受けた最後の報告。tako はそのペインの報告を即座に捨てる */
  ended: boolean
}

/** 描いているもの（tako_core::claude_mod::ModRenders）。tako はこれを見て自分の表示を引っ込める */
export type TakoRenders = {
  /** 直近の帯の描画で tako の行を描いたか */
  band: boolean
  /** 使用制限・ctx のバーを描いた置き場（描いていなければ欠ける） */
  usage_bar?: 'prompt_hint' | 'band'
  /** 直近の帯の描画で描いたボタンの数 */
  buttons: number
  /** 起きてから帯（AbovePrompt）のフックが呼ばれたか（偽で hint_hook が真 = 外側の他の mod に帯を隠された） */
  band_hook: boolean
  /** 起きてから入力欄の下の行（PromptHint）のフックが呼ばれたか */
  hint_hook: boolean
  /**
   * 直近の帯の描画で押せる形（Copy / Run のボタンつき）で描いたコマンドカードの id（#1963）。
   * 応答に view.cards が無い（tako が描かせない）ときは欠ける。tako は載った id を GPUI のカード帯から外す
   */
  cards?: number[]
  /**
   * チャット風の描画で今あてている組（#1964。応答の view.chat をそのまま）。応答に view.chat が無い
   * （A/B・古い tako）ときは欠ける。GUI モードで tako はこれがあるペインのチャットを mod に任せうる
   */
  chat?: TakoChatRenders
}

/** チャット風の描画で今あてている組（tako_core::claude_mod::ModChatRenders） */
export type TakoChatRenders = {
  bubble: boolean
  code_copy: boolean
  tool_summary: boolean
  /** 会話の行が足されるたびにすぐ報告している（view.chat.notify を受けた） */
  notify: boolean
}

/**
 * ボタンを押した結果（tako_core::claude_mod::ModPress）。ラベル・コマンド・入力欄へ入れる文は載せない。
 * card_* はコマンドカードの帯のボタン（#1963。card_copy_cli = $.ui.copy が拒まれて tako の CLI で写した）。
 * code_copy はチャット風の描画のコードのコピー（#1964。会話の行のボタンと帯の「最新のコードをコピー」）
 */
export type TakoPress = {
  kind: 'slash' | 'tako' | 'shell' | 'prompt' | 'card_copy' | 'card_copy_cli' | 'card_run' | 'card_dismiss' | 'code_copy'
  ok: boolean
  /** 押した時刻（epoch ms） */
  at: number
}

/** 帯（プロンプトの上の 1 行）の状態（tako_core::claude_mod::ModBand） */
export type TakoBand = {
  /** 利用者が帯を隠している（$.store の band） */
  hidden: boolean
  /** 直近の描画で帯を描いたか */
  shown: boolean
  /** 直近の描画の帯の本文の桁（AbovePrompt の bodyColumns） */
  columns?: number
  /** 描いた区切りの種類（左から。tako / pane / tab / workers / attention / ctx / five_hour …） */
  segments: string[]
  /** トグルを最後に変えた時刻（epoch ms） */
  toggled_at?: number
}

/** worker の状態（tako_core::claude_mod::WorkerState） */
export type TakoWorkerState = 'busy' | 'idle' | 'waiting' | 'limited' | 'failed' | 'unknown'
/** 要注意の理由（tako_core::claude_mod::Attention） */
export type TakoAttention = 'permission' | 'question' | 'dialog' | 'limited' | 'failed'

export type TakoWorker = {
  pane: number
  name: string
  state: TakoWorkerState
  attention?: TakoAttention
}

/** tako が `tako mod report` の応答（tako.view）で返す帯・サイドバーの材料（tako_core::claude_mod::BandView） */
export type TakoView = {
  pane: number
  pane_title?: string
  tab_title?: string
  /** tako の表示言語（ja / en） */
  lang: string
  worker_count: number
  attention: number
  /** 要注意を先に、上限まで */
  workers: TakoWorker[]
  /** 帯に出す警告（tako が閾値を超えたと判断したものだけ） */
  warnings: { kind: string; percent: number; resets_at?: number }[]
  /** サイドバー用（閾値に関わらず） */
  ctx?: TakoContext
  rate_limits: { kind: string; percent: number; resets_at?: number }[]
  thresholds: { ctx_percent: number; limit_percent: number }
  /**
   * 帯のトグルの中継（at は epoch ms。$.store の時刻より新しいときだけ従う）。正本は ui.json の
   * band.hidden / toggled_at（#1960）で、`tako mod band on|off`・`tako mod ui set band.hidden`・
   * この mod の報告の取り込みのどれで変わっても同じ形で届く
   */
  band_request?: { hidden: boolean; at: number }
  /** 定型の UI 設定（#1960。tako が検証した値だけが届く。古い tako の応答には無い） */
  ui?: TakoUi
  /**
   * 使用制限・ctx のバーを描くか（#1962。tako が決める: 置き場が off・利用者の statusLine が既に数値を
   * 出している = 描かない）。A/B と古い tako の応答には無い
   */
  usage_bar?: { draw: boolean; reason?: 'off' | 'status_line' }
  /** tako / shell のボタンを押したときに叩く CLI の引数（ボタンの id → tako の後ろの argv。tako が組む） */
  button_args?: Record<string, string[]>
  /** 帯の描き方。's3' = #1962 前（next を包まない・ボタンとバーなし。A/B の TAKO_1877_S7_LEGACY） */
  band_style?: 's3'
  /**
   * このペインのコマンドカード（#1963。tako が描かせると決めたときだけ届く = ui.json の cards.place が
   * tako・A/B の TAKO_1963_LEGACY / TAKO_1877_S7_LEGACY・古い tako の応答には無い）
   */
  cards?: TakoCards
  /**
   * チャット風の描画（#1964。A/B の TAKO_1964_LEGACY / TAKO_1877_S7_LEGACY・古い tako の応答には無い =
   * 何も描かない）。何を描くかは tako が ui.json の chat × 表示モードで決める
   */
  chat?: TakoChat
}

/** チャット風の描画（tako_core::claude_mod::ChatView） */
export type TakoChat = {
  /**
   * どの組か: gui = GUI モードで mod がチャットを持つ / terminal = ターミナル表示・GPUI のチャットの裏
   * （ui.json の always だけ）/ off = chat.place が tako（何も描かない）
   */
  mode: 'gui' | 'terminal' | 'off'
  /** 利用者の発話（composer / bridge）を右寄せの吹き出しに描く */
  bubble: boolean
  /** AI の返答のコードブロックの下にコピーのボタン、帯に「最新のコードをコピー」 */
  code_copy: boolean
  /** ツールの呼び出しを 1 行の要約に描く（ToolGroup は展開して 1 呼び出し 1 行） */
  tool_summary: boolean
  /** 帯の「最新のコードをコピー」のホットキー（tako がボタン・カードと重ならない英小文字を選ぶ） */
  hotkey: string
  /** 会話の行が足されたらすぐ報告する（GUI モードで GPUI のチャットが表に出ているペイン） */
  notify: boolean
}

/** コマンドカード（tako_core::claude_mod::CardsView）。正本は tako の store（`tako show-command --list`） */
export type TakoCards = {
  /** 帯のカードのボタンのホットキー（tako が ui.json のボタンと重ならない英小文字を選ぶ。数字は使わない） */
  hotkeys: { copy: string; run: string; next: string; dismiss: string }
  /**
   * 会話の行のカードにクリックで押す「実行 / コピー」を置いてよいか（#2159。tako がこのペインの TUI へ
   * 左クリックを渡す = `tako mouse` が on ∧ A/B でない）。置くのはさらに全画面（viewport.isFullscreen）の
   * 端末のときだけ。偽なら帯で押す案内だけ（#1963 の形）。帯のボタンはどちらでも描く（キーの口）
   */
  click: boolean
  /** 古い順（store の並び）。帯は新しいものから選ぶ */
  items: TakoCard[]
}

/** カード 1 枚（tako_core::claude_mod::CardView） */
export type TakoCard = {
  /** tako のカード id（`tako show-command --card N`。帯と会話の行の「カード N」） */
  id: number
  label?: string
  commands: TakoCardCommand[]
  /** 閉じるで叩く CLI の引数（tako の後ろの argv。tako が組む） */
  dismiss_args: string[]
}

/** カードのコマンド 1 件（tako_core::claude_mod::CardCommandView） */
export type TakoCardCommand = {
  /** 論理文字列（AI が渡したまま。画面の折り返しは混ざらない = Copy に渡すのはこれ） */
  text: string
  /** $.ui.copy が拒まれたときに叩く CLI の引数（tako の show-command --copy） */
  copy_args: string[]
  /** Run で叩く CLI の引数（tako の show-command --run = 新しいペインで実行・スマホと同じ実行記録） */
  run_args: string[]
  /** 最後の実行の記録（#1724。未実行は欠ける） */
  run?: { pane: number; state: 'running' | 'exited' | 'closed'; exit_code?: number; count: number }
}

/** 帯に並べる区切り（tako_core::claude_mod_ui::BandSegment） */
export type TakoBandSegment = 'pane' | 'tab' | 'workers' | 'attention' | 'ctx' | 'limits' | 'buttons' | 'card'
/** カード・チャットを誰が描くか */
export type TakoPlace = 'auto' | 'mod' | 'tako'
/** チャット風の描き方をいつ出すか */
export type TakoChatShow = 'always' | 'gui_only' | 'off'
/** 色は Claude Code のテーマのキーだけ（ThemeKey の部分集合） */
export type TakoThemeColor =
  | 'text'
  | 'inactive'
  | 'subtle'
  | 'suggestion'
  | 'remember'
  | 'success'
  | 'error'
  | 'warning'
  | 'merged'
  | 'claude'
  | 'permission'
  | 'planMode'
  | 'autoAccept'
  | 'ide'
/** ボタンの動作（4 種の定型だけ。任意の JS は持たない） */
export type TakoButtonAction =
  | { kind: 'slash'; command: 'compact' | 'clear' | 'context' | 'cost' | 'model' | 'effort' | 'tako' }
  | {
      kind: 'tako'
      op:
        | 'split-right'
        | 'split-down'
        | 'session-restart-harness'
        | 'session-restart-handoff'
        | 'limit-resume-on'
        | 'limit-resume-off'
        | 'background'
        | 'close'
        | 'open-cwd'
    }
  | { kind: 'shell'; command: string }
  | { kind: 'prompt'; text: string }
/** カスタムボタン（8 個まで・label 16 桁・hotkey は数字か英小文字 1 字で重複なし） */
export type TakoButton = { id: string; label: string; hotkey: string; action: TakoButtonAction }

/** 定型の UI 設定（tako_core::claude_mod_ui::UiConfig = `<data_dir>/claude-mod/ui.json`） */
export type TakoUi = {
  schema_version: 1
  band: { hidden: boolean; segments: TakoBandSegment[]; toggled_at?: number }
  usage_bar: { place: 'prompt_hint' | 'band' | 'off'; items: ('five_hour' | 'seven_day' | 'ctx')[] }
  buttons: TakoButton[]
  cards: { place: TakoPlace }
  chat: { place: TakoPlace; bubble: TakoChatShow; code_copy: boolean; tool_summary: TakoChatShow }
  colors: { accent: TakoThemeColor; warn: TakoThemeColor; dim: TakoThemeColor }
}

declare module 'claude-code' {
  interface PluginState {
    tako: {
      /** 最後に受け取った tako の材料（無い・古い = null で帯を描かない） */
      view: TakoView | null
      /** 帯を隠すトグル（$.store の band の写し。描画が購読する） */
      bandHidden: boolean
      /** 使用制限の窓ごとの観測時刻（#1903。描画は読まない） */
      limitsSeen: TakoLimitsSeen
      /** 帯で選んでいるカードのコマンド（#1963。null = いちばん新しいカードの 1 件目） */
      cardCursor: { card: number; index: number } | null
      /**
       * 最新の AI の返答のコードブロック（#1964。帯の「最新のコードをコピー」が写す。**報告には載せない**）
       */
      chatCodes: string[]
      /** ツールの要約から「詳細」で開いた呼び出しの tool_use_id（#1964。開いた行はエンジンの描画に戻す） */
      toolOpen: string[]
    }
  }
}
